INSERT INTO `packages` VALUES
(1,9,NULL,NULL,1,'travel_package',NULL,NULL,'egypt-luxury-vacation-package-10-day-cairo-luxor-aswan-nile-cruise','{\"en\":\"Egypt Luxury Vacation package 10-Day Cairo, Luxor, Aswan & Nile Cruise\"}',NULL,'{\"en\":\"Experience 10 days of luxury in Egypt! Private tours of Cairo\'s Pyramids & GEM, then a 5-star Nile Cruise from Luxor to Aswan. All-inclusive historical escape.\"}','{\"en\":\"<p class=\\\"query-text-line ng-star-inserted\\\">Egypt Luxury Vacation package 10-Day Cairo, Luxor, Aswan &amp; Nile Cruise, Bask in the timeless majesty of ancient Egypt on an immersive journey through the land of the pharaohs, exploring its quintessential archaeological treasures with an expert Egypt tour pro Egyptologist, and cruise for four nights along the Nile aboard stylish.<\\/p>\\r\\n<p class=\\\"query-text-line ng-star-inserted\\\">&nbsp;<\\/p>\\r\\n<p class=\\\"query-text-line ng-star-inserted\\\"><strong>Egypt Tour Pro Advantages<\\/strong><\\/p>\\r\\n<ul>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Embark on a four-night Nile river cruise, gliding in comfort through stirring desert landscapes and going ashore to discover ancient Egypt&rsquo;s most awe-inspiring sites.<\\/li>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Explore the Egyptian Museum of Antiquities (or the Grand Egyptian Museum, upon its opening) to view a vast trove of artifacts.<\\/li>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Venture inside one of the pyramids and view the enigmatic Great Sphinx on the Giza Plateau<\\/li>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Descend into the tomb of King Tut and the colorful tomb of Seti I, father of legendary Ramses II, in the Valley of the Kings.<\\/li>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Marvel at the colossal statues and towering colonnade of the sprawling Temple of Luxor, and listen as your expert &nbsp;Egyptologist deciphers the hieroglyphs carved upon them.<\\/li>\\r\\n<li class=\\\"query-text-line ng-star-inserted\\\">Journey to Abu Simbel to set eyes upon the imposing twin temples of Ramses II and Queen Nefertari.<\\/li>\\r\\n<\\/ul>\"}','days',10,NULL,9,'{\"en\":\"10 Days, 9 Nights\"}',NULL,2800.00,NULL,2800.00,NULL,2800.00,NULL,NULL,3,0,99,0,0,2800.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.00,0,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,1,'2025-09-19 16:05:53',10,'{\"en\":\"Egypt Luxury Vacation package 10-Day Cairo, Luxor , Aswan & Nile Cruise\"}','{\"en\":\"Egypt Luxury Vacation package 10-Day Cairo, Luxor, Aswan & Nile Cruise: Experience 10 days of luxury in Egypt! Private tours of Cairo\'s Pyramids & GEM, then a 5-star Nile Cruise from Luxor to Aswan. All-inclusive historical escape.\"}',NULL,NULL,NULL,NULL,'legacy_rails_travel_package','21','Egypt-Luxury-Vacation-package-10-Day-Cairo-Luxor-Aswan-&-Nile-Cruise','2026-09-13 09:54:41','2025-09-19 16:05:53','2026-04-01 14:50:29',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,NULL),
(2,10,NULL,NULL,1,'travel_package',NULL,NULL,'cairo-luxor-aswan-and-abu-simbel-9-days-with-sightseeing-and-domestic-flight','{\"en\":\"9 Days Egypt Tour: Cairo, Luxor, Aswan & Abu Simbel with Flights & Sightseeing\"}',NULL,'{\"en\":\"Embark on an epic 9-day journey to Egypt. Explore Cairo, Luxor, Aswan & Abu Simbel. This all-inclusive sightseeing tour covers ancient wonders. Book now!\"}','{\"en\":\"<p>Explore Cairo, Luxor, Aswan &amp; Abu Simbel: 9-Day Journey, Embark on an extraordinary exploration of Egypt with our meticulously crafted 9 Days 8 Nights Travel Package to Cairo, Luxor, and Aswan. Dive into the profound history and enchanting allure of this extraordinary nation.<\\/p>\\r\\n<p>Commence your voyage in Cairo, where you will uncover ancient marvels such as the Pyramids of Giza and the iconic Sphinx. Journey on a captivating Nile cruise from Aswan to Luxor, beholding the serene landscapes and timeless treasures en route. Delve into the grandeur of Luxor&rsquo;s temples and the awe-inspiring Abu Simbel, creating an indelible sojourn through the core of Egypt.<\\/p>\\r\\n<p><strong>Highlights<\\/strong><\\/p>\\r\\n<ul>\\r\\n<li>\\r\\n<p>Visit Best of Cairo attractions.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Visit Best of Luxor attractions.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Enjoy Cruising trip on 5 Stars cruise.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Private Tours and Transfers.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Private Tour guide will accompany with you everywhere you go.<\\/p>\\r\\n<\\/li>\\r\\n<\\/ul>\\r\\n<p><strong>Language<\\/strong> Operated in: English, German, French, Spanish, Russian<\\/p>\"}','days',9,NULL,8,'{\"en\":\"9 Days, 8 Nights\"}',NULL,1899.00,NULL,1899.00,NULL,1899.00,NULL,NULL,3,0,89,0,0,1899.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.00,0,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,1,'2025-09-20 16:51:21',1,'{\"en\":\"9 Days Egypt Tour: Cairo, Luxor, Aswan & Abu Simbel with Flights & Sightseeing\"}','{\"en\":\"Embark on an epic 9-day journey to Egypt. Explore Cairo, Luxor, Aswan & Abu Simbel. This all-inclusive sightseeing tour covers ancient wonders. Book now!\"}',NULL,NULL,NULL,NULL,'legacy_rails_travel_package','22','cairo-luxor-aswan-and-abu-simbel-9-days-with-sightseeing-and-domestic-flight','2026-09-13 09:54:41','2025-09-20 16:51:21','2026-04-01 14:47:56',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,1,NULL),
(3,11,NULL,NULL,1,'travel_package',NULL,NULL,'explore-egypt-10-day-cultural-tour-red-sea-holiday','{\"en\":\"Explore Egypt 10-Day Cultural Tour & Red Sea Holiday\"}',NULL,'{\"en\":\"Embark on the \\\"Explore Egypt 10-Day Cultural Tour & Red Sea Holiday.\\\" Discover ancient wonders from the Giza Pyramids to Luxor and relax on Red Sea.\"}','{\"en\":\"<p>Explore Egypt 10-Day Cultural Tour &amp; Red Sea Adventure &ndash; Your Ultimate Journey from Ancient Wonders to Coastal Bliss. Embark on an unforgettable 10-day odyssey that perfectly blends Egypt&rsquo;s awe-inspiring ancient history with the serene beauty of its Red Sea coast.<\\/p>\\r\\n<p>Our meticulously crafted &ldquo;Explore Egypt&rdquo; tour invites you to delve into the heart of a civilization that shaped the world, before unwinding on the sun-kissed beaches of Hurghada. This adventure promises an immersive cultural experience and rejuvenating relaxation, creating memories that will last a lifetime.<\\/p>\\r\\n<p><strong>Highlights:<\\/strong><\\/p>\\r\\n<ul>\\r\\n<li>\\r\\n<p>Explore the Giza Pyramid complex.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Discover the treasures of the Egyptian Museum.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Cruise the Nile and visit ancient temples.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Unwind at an all-inclusive resort in Hurghada.<\\/p>\\r\\n<\\/li>\\r\\n<li>\\r\\n<p>Dive into snorkeling adventures in the Red Sea.<\\/p>\\r\\n<\\/li>\\r\\n<\\/ul>\"}','days',10,NULL,9,'{\"en\":\"10 Days, 9 Nights\"}',NULL,1450.00,NULL,1450.00,NULL,1450.00,NULL,NULL,0,0,0,0,0,1450.00,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.00,0,1,5,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,1,'2025-09-20 17:18:37',2,'{\"en\":\"Explore Egypt 10-Day Cultural Tour & Red Sea Holiday\"}','{\"en\":\"Embark on the \\\"Explore Egypt 10-Day Cultural Tour & Red Sea Holiday.\\\" Discover ancient wonders from the Giza Pyramids to Luxor and relax on Red Sea....\"}',NULL,NULL,NULL,NULL,'legacy_rails_travel_package',